import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const m=JSON.parse('{"title":"第101章 坐下来了","description":"","frontmatter":{},"headers":[],"relativePath":"第101章_坐下来了.md","filePath":"第101章_坐下来了.md"}'),o={name:"第101章_坐下来了.md"};function r(n,p,s,c,i,d){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第101章-坐下来了" tabindex="-1">第101章 坐下来了 <a class="header-anchor" href="#第101章-坐下来了" aria-label="Permalink to &quot;第101章 坐下来了&quot;">​</a></h1><p>我们第一次坐下来讲话，是毕业那年的七月。</p><p>那一次不是我们约的。</p><p>是账。</p><p>她那年在国内接了一个团购的活，做二次分装。</p><p>她那边走不通快递，她需要一个人在我们这边收货、拆包、按单发出去。</p><p>她找我。</p><p>她说，我要找一个人帮我发东西。</p><p>我说，你找我。</p><p>她说，我这边只有你。</p><p>我说，为什么是我。</p><p>她说，因为你不问。</p><p>她说，我要是找何叶，她第一天就会问这人是谁。</p><p>她说，我要是找我妹，她拿去玩了。</p><p>她说，你什么都不问。</p><p>我说，我今年问了一句。</p><p>她说，你那句我记着呢，你后来也没讲。</p><p>她说，你就当我没听到。</p><p>我说，行。</p><p>她说，那我开始讲了。</p><p>她说，一箱大概五十件，我一个月发两箱。</p><p>她说，你帮我拆开，按我的单子分装，装好，贴单，发出去。</p><p>她说，一单我给你一块五。</p><p>我说，不用。</p><p>她说，你必须拿。</p><p>我说，为什么。</p><p>她说，因为你不拿你就又是白干。</p><p>她说，你一白干你讲话就开始绕。</p><p>她说，你绕起来我接不住。</p><p>她说，你收了钱，我们就是办事，办事的人心里是平的。</p><p>我说，那我收。</p><p>她说，对。</p><p>她说，我们周六见一面，我把单子当面给你讲一次，线上讲不清。</p><p>我说，好。</p><p>周六是七月八号。</p><p>她定的那个地方是一个奶茶店。</p><p>她选那个店的原因，她后来跟我讲了。</p><p>她说，那家店有六个位置靠窗。</p><p>她说，靠窗那排坐得下两个人，而且背后没有人。</p><p>她说，我背后有人我不敢讲话。</p><p>她说，我选了三家店，最后选了这里。</p><p>我说，你选店还查背后有没有人。</p><p>她说，我这辈子做事都查这个。</p><p>两点我到了。</p><p>她已经在。</p><p>她坐在那一排最里面那个位子。</p><p>我看见她的时候，我第一反应是很土的一句话。</p><p>我想的是：她比照片老。</p><p>我那时候不知道&quot;老&quot;这个字怎么来的。</p><p>她那年二十四，我二十四。</p><p>她头发扎着，脸上有一块很小的、在眼睛下面的斑。</p><p>她手上戴着一只很旧的塑料表。</p><p>她穿一件深色的短袖，肘那里有一道折痕。</p><p>她抬头看我。</p><p>她说，你来了。</p><p>我说，我来了。</p><p>她说，你坐。</p><p>我坐下来。</p><p>我把包放在桌上，我又拿下来，我放在脚边。</p><p>那个动作我做了两次。</p><p>她看着我笑了一下。</p><p>她说，你这个人，你在椅子上坐不住。</p><p>我说，我坐着。</p><p>她说，你屁股往前三分之二。</p><p>我说，什么。</p><p>她说，你现在坐的是那种随时要走的位子。</p><p>她说，你以前在电话亭外头等人就是这个坐法。</p><p>她说，你放松一点，我今天只有一个钟头。</p><p>我往后靠了。</p><p>那个椅子背后是空的，靠下去那一下我反而紧张。</p><p>她先把一个袋子推到桌子中间。</p><p>她说，这是单子。</p><p>她说，我今天不讲怎么发，我今天讲三件事。</p><p>我说，你说。</p><p>她说，第一件，钱怎么走。</p><p>她说，第二件，出错怎么办。</p><p>她说，第三件，你别问我为什么找你。</p><p>我说，第一件你说。</p><p>她讲了二十分钟。</p><p>她讲得非常清楚。</p><p>清楚到我从包里拿出笔，在一张纸上记下来。</p><p>我记的时候，她在那儿看着我。</p><p>她说，你真的写。</p><p>我说，我习惯。</p><p>她说，你写这些，我明天就看不到了。</p><p>我说，我给自己看。</p><p>她说，你以后不要写。</p><p>我说，为什么。</p><p>她说，因为你写下来的东西，你就不会错。</p><p>她说，你不会错，我这边出了错，就是我在错。</p><p>她说，我们两个里必须有一个人会错。</p><p>她说，我不太愿意那个人是我。</p><p>我说，那我也不愿意是你。</p><p>她说，那你别记。</p><p>我说，好，我不记。</p><p>我那天把笔放回包里。</p><p>我一个字也没写。</p><p>那一个钟头里，第二件、第三件她讲完了。</p><p>第三件她讲得最短。</p><p>她说，你别问为什么找我。</p><p>她说，因为我要是回答了你这个问题，我今天下午回去就要开始想我们是什么。</p><p>她说，我今天下午还要去一个地方，我不能带着那个想。</p><p>我说，那你今天这个决定是什么。</p><p>她说，这个是收人。</p><p>她说，我今天收了一个人。</p><p>她说，这个决定很小，它不牵扯任何别的东西。</p><p>她说，我们把它当成一件事定下来。</p><p>那天下午两点五十，她站起来。</p><p>她说，我先走了。</p><p>我说，我送。</p><p>她说，不用，我打车。</p><p>她说，你坐在这儿再十分钟。</p><p>我说，为什么。</p><p>她说，因为你要是跟我一起出去，我们在那门口要站一会儿。</p><p>她说，那个门口站着会说话。</p><p>她说，我们今天不要说那种话。</p><p>我说，哪种话。</p><p>她说，你知道哪种。</p><p>她走了。</p><p>我一个人坐在那张椅子上。</p><p>桌上留着她那杯没喝完的东西。</p><p>那一杯底下有一圈水痕，压得在木头上很白。</p><p>我把那个杯子往我这边挪了一点，我又挪回去了。</p><p>后来我发现一件事。</p><p>桌上那个付款的单子不见了。</p><p>我出去问那个店员。</p><p>我说，刚刚坐这个位的人付了吗。</p><p>他说，付了。</p><p>我说，她一个人付两杯？</p><p>他说，她付的时候讲了，她说这两杯都是公事。</p><p>我那天下午在回去的路上想这句话想了很久。</p><p>她说的是“这两杯都是公事”。</p><p>她今天把两杯的钱一起付了，是因为她要这个下午从第一分钟到最后一分钟都是公事。</p><p>她不能欠我一杯饮料。</p><p>一杯三十一块的饮料，在她那里是一句可以拿来讲的东西。</p><p>她今天把它斩了。</p><p>而我那天下午坐在那张椅子上，连一杯三十一块都没有付成。</p><p>十点五十我出去。</p><p>我在那个门口站了一下。</p><p>我看见她过那条马路，她走得不快。</p><p>她走到对面，没有回头。</p><p>我那天下午在回去的公交上，想的是她在电话里说的那一句。</p><p>她说，我这辈子做过的所有决定，都是在没有人的时候做的。</p><p>她说，今天这个决定是在有人看着的情况下做的。</p><p>她说，所以我今天做得很顺利。</p><p>我那时候以为她说的是收我做事这件事很顺利。</p><p>很多年以后我才反应过来，她那天讲的顺利，是说她终于有一件可以当着人做的正事。</p><p>那件事里没有我。</p><p>我只是那件正事里的一颗螺丝。</p><p>而我那天下午很高兴。</p><p>因为我第一次在她那里有一个不尴尬的位置。</p>',151)])])}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
